template:
enum Status {
    Pending,
    Active(u32),
    Finished,
}

fn process(status: Status, max: u32) -> &'static str {
    match status {
        Status::Active(p) ⟦guard⟧ => "high priority",
        Status::Active(_) => "normal priority",
        ⟦fallback⟧ => "not active",
    }
}

fn main() {
    println!("{}", process(Status::Active(10), 5));
}

tests:
#[test]
fn handles_priorities() {
    assert_eq!(process(Status::Active(10), 5), "high priority");
    assert_eq!(process(Status::Active(3), 5), "normal priority");
    assert_eq!(process(Status::Pending, 5), "not active");
    assert_eq!(process(Status::Finished, 5), "not active");
}
